"""Report exported collision complexity without changing assets or geometry."""
from pathlib import Path
from collections import Counter,defaultdict
import json,statistics
r=Path(__file__).resolve().parents[1];p=json.loads((r/'unreal/prop_placements.json').read_text());e=json.loads((r/'unreal/environment_manifest.json').read_text())
uses=Counter(x['asset_name'] for x in p['placements']);assets=sorted(p['assets'],key=lambda a:-a['collision_hulls']);family=defaultdict(lambda:{'canonical_assets':0,'placements':0,'canonical_hulls':0,'placed_hulls':0,'max_hulls_per_asset':0})
for a in assets:
 f=family[a['family']];n=a['collision_hulls'];u=uses[a['asset_name']];f['canonical_assets']+=1;f['placements']+=u;f['canonical_hulls']+=n;f['placed_hulls']+=n*u;f['max_hulls_per_asset']=max(f['max_hulls_per_asset'],n)
counts=[a['collision_hulls'] for a in assets]
report={'source_sha256':p['source_blend_sha256'],'performance_verified':False,'prop_canonical_hulls':sum(counts),'prop_placed_hull_instances':sum(a['collision_hulls']*uses[a['asset_name']] for a in assets),'prop_assets':len(assets),'prop_placements':len(p['placements']),'per_asset_min':min(counts),'per_asset_median':statistics.median(counts),'per_asset_max':max(counts),'environment_hulls':sum(a['ucx_hulls'] for a in e['assets']),'families':dict(sorted(family.items(),key=lambda x:-x[1]['placed_hulls'])),'highest_complexity_assets':[{'asset_name':a['asset_name'],'source_exemplar':a['source_exemplar'],'family':a['family'],'hulls':a['collision_hulls'],'placements':uses[a['asset_name']]} for a in assets[:25]]}
(r/'qa/collision_complexity.json').write_text(json.dumps(report,indent=2)+'\n')
lines=['# Collision budget review','', 'Geometric validation is not performance validation. These meshes are not simulating physics by default, but imported simple collision still adds memory/cooking and query cost. Profile the actual game before shipping.','',f"- Props: {len(assets)} canonical assets, {len(p['placements'])} independent actor placements",f"- Canonical prop UCX hulls: {sum(counts):,}; placed hull instances: {report['prop_placed_hull_instances']:,}",f"- Per canonical prop: minimum {min(counts)}, median {statistics.median(counts):g}, maximum {max(counts)} hulls",f"- Environment: {report['environment_hulls']:,} separate primitive hulls across {len(e['assets'])} tiles",'', '## Highest per-asset complexity','']
for a in assets[:15]:lines.append(f"- {a['asset_name']}: {a['collision_hulls']} hulls, {uses[a['asset_name']]} placement(s); source {a['source_exemplar']}")
lines+=['','## Optimization priorities','','Small ticket rolls, coiled hose, paint cans and buckets use deliberate family-specific simpler proxies where their tiny openings cannot fit a player. Review the export collision-proxy ledger for each exception. Preserve gameplay-useful openings in cars, pallets, benches, gates and corridors; do not replace those whole assemblies with convex hulls. Test the player capsule and possession trace against the supplied proxies.','','Review whether static small props need query-only versus QueryAndPhysics in the actual project; do not change it without testing the existing gameplay. Keep every eligible copy a separate StaticMeshActor. Use scene-query and physics-cooking profiling, not just draw-call counts. Canonical assets can share cooked collision, while placed actor shapes still matter for broadphase/query work.','','For scenery, inspect large spatial tiles for overbroad collision bounds and consider smaller collision groupings where profiling warrants it. Thin decoration and foliage omissions are intentional and must not be filled with a full-tile hull.','','Detailed family distribution and top 25 assets: `../qa/collision_complexity.json`. Unreal cooking, frame-time and trace benchmarks remain untested.']
(r/'docs/COLLISION_BUDGET.md').write_text('\n'.join(lines)+'\n');print({k:v for k,v in report.items() if k not in ('families','highest_complexity_assets')})
